public class Main {
    public static void main(String[] args) {
        String nama = "Budi";
        int umur = 17;

        System.out.println("Nama: " + nama);
        System.out.println("Umur: " + umur);

        umur = 18;
        System.out.println("Tahun depan: " + umur);
    }
}

